import { withAuth } from "@workos-inc/authkit-nextjs";

export type User = {
  id: string;
  email: string;
  name: string;
  createdAt: string;
  // WorkOS user id, set once the user has signed in through AuthKit.
  workosId?: string;
};

const users: User[] = [
  { id: "1", email: "ada@example.com", name: "Ada", createdAt: "2026-01-04" },
  { id: "2", email: "grace@example.com", name: "Grace", createdAt: "2026-02-11" },
];

export async function listUsers(): Promise<User[]> {
  return users;
}

export async function getUser(id: string): Promise<User | undefined> {
  return users.find((u) => u.id === id);
}

type AuthUser = {
  id: string;
  email: string;
  firstName: string | null;
  lastName: string | null;
  createdAt: string;
};

// Links a WorkOS identity to a local user: match by WorkOS id, then by email
// (so existing users keep their record), otherwise create one on first sign-in.
function upsertFromAuth(authUser: AuthUser): User {
  const email = authUser.email.toLowerCase();
  let user =
    users.find((u) => u.workosId === authUser.id) ??
    users.find((u) => u.email.toLowerCase() === email);

  if (!user) {
    const name =
      [authUser.firstName, authUser.lastName].filter(Boolean).join(" ") || email.split("@")[0];
    user = {
      id: String(users.length + 1),
      email,
      name,
      createdAt: authUser.createdAt.slice(0, 10),
    };
    users.push(user);
  }

